// TH14 v1.00b Stage 4 Boss / BossBCard3（st04bs2.ecl.txt:559-615），路线B。
// 源→目标总对应：
//   577-581 spell(60,3000,…)+setInterrupt(0,0,3000,"BossBDead") -> spell_begin + 超时后 boss_dead
//   583-584 moveLimit(0,128,280,64)+movePosTime(60,4,160,128)  -> boss_x_move 逐帧夹界
//   591/593/595 三个 async 发射流                            -> stream_at / stream_at_h / stream_at_l
//   599-613 左右横移 + at2                                  -> card_pattern 循环 + at2_fire
// 共用取舍：普通掉落/计分/音效/ANM/震屏、卡前一个符卡的清理（Ecl_EtBreak 等）按政策省略。

const TIME_LIMIT: int = 3624;
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 60;
const SPELL_TIME: int = 3000;

const TH14_BIG_BALL: int = 640;
const TH14_NOTE_BLUE: int = 992;
const TH14_NOTE_YELLOW: int = 1008;

// 源 moveLimit(0.0f, 128.0f, 280.0f, 64.0f)：x∈[-140,140]、y∈[96,160]；本卡 y 恒 128。
const LIMIT_X: fx = 140fx;

// 源 643-646：四条 ANGLE_ACCEL（etEx async=0，顺序执行）——r 为每帧速度增量，
// s 为每帧角速度。逐 volley 抽样后按值传入；四段结束后清 accel 与角速度。
xformdef S4B12_CURVE(w1: angle, w2: angle, w3: angle, w4: angle) {
    set_accel(-0.036fx);
    @40 set_ang_vel(w1);
    set_accel(0.015fx);
    @40 set_ang_vel(w2);
    set_accel(-0.016fx);
    @40 set_ang_vel(w3);
    set_accel(0fx);
    set_ang_vel(w4);
    wait(500);
    set_accel(0fx);
    set_ang_vel(0deg);
}

// 源 584/603/609 的 movePosTime + 源 583 限位：每帧按插值推进并把 x 夹到 ±140。
// quad_out=1 对应源 mode 4（二次减速）；0 对应源 mode 0（线性）。
sub boss_x_move(target: fx, frames: int, quad_out: int) {
    var x0: fx = $self_x;
    for k in 0..frames {
        var u: fx = ((k + 1) as fx) / (frames as fx);
        var e: fx = u;
        if quad_out != 0 {
            var inv: fx = 1fx - u;
            e = 1fx - inv * inv;
        }
        var nx: fx = x0 + (target - x0) * e;
        if nx > LIMIT_X { nx = LIMIT_X; }
        if nx < (0fx - LIMIT_X) { nx = 0fx - LIMIT_X; }
        move_vel_xy(0, nx - $self_x, 0fx, EASE_LINEAR);
        wait(1);
    }
}

// 源 636-646（at/at_h/at_l 共用）：出弹点 = etOffsetAbs(±FINAL_X*k, 460) 与
// etOffset(RANDF2*16, 0) 合成；再加源 ANIM(a=1) 的 position -= 4*velocity 退位移
// （角度恒 -90°、速度 3.2 → (0, +12.8)，故 y=472.8）。随后四条 ANGLE_ACCEL
// 的角速度按源顺序各抽一次：0.008rad(≈83BAM)、0.008、0.008、0.016rad(≈167BAM)。
sub note_volley(factor: fx) {
    var j: int = (rand(65536) - 32768) * 16 / 32768;
    var x: fx = (0fx - $self_x) * factor + (j as fx);
    var w1: int = (rand(65536) - 32768) * 83 / 32768;
    var w2: int = (rand(65536) - 32768) * 83 / 32768;
    var w3: int = (rand(65536) - 32768) * 83 / 32768;
    var w4: int = (rand(65536) - 32768) * 167 / 32768;
    sh_offset_abs(0, x, 472.8fx);
    sh_xform(0, S4B12_CURVE(w1 as angle, w2 as angle, w3 as angle, w4 as angle));
    sh_fire(0);
}

// 源 617-673 BossBCard3_at（全难度）：E 10发/10帧，N/H/L 15发/6帧；
// E/N 源 type40 黄音符，H/L 源 type39 蓝音符；出弹点 -FINAL_X*1.2。
async sub stream_at() {
    var rank: int = global(GVAR_RANK);
    var volleys: int = 15;
    var gap: int = 6;
    var shape: int = TH14_NOTE_BLUE;
    if rank <= RANK_NORMAL {
        shape = TH14_NOTE_YELLOW;
        if rank == RANK_EASY { volleys = 10; gap = 10; }
    }
    sh_reset(0);
    sh_sprite(0, shape, 0);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 1, 1);
    sh_angle(0, -90deg, 0deg);
    sh_speed(0, 3.2fx, 0fx);
    loop {
        for i in 0..volleys {
            note_volley(1.2fx);
            wait(gap);
        }
        wait(gap);
    }
}

// 源 688-744 BossBCard3_at_h（仅 H/L）：10发/6帧；出弹点 -FINAL_X*0.9。
async sub stream_at_h() {
    sh_reset(0);
    sh_sprite(0, TH14_NOTE_BLUE, 0);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 1, 1);
    sh_angle(0, -90deg, 0deg);
    sh_speed(0, 3.2fx, 0fx);
    loop {
        for i in 0..10 {
            note_volley(0.9fx);
            wait(6);
        }
        wait(6);
    }
}

// 源 746-802 BossBCard3_at_l（仅 L）：15发/6帧；出弹点 +FINAL_X*1.2；
// 循环尾 !LO 为 20 帧额外等待。
async sub stream_at_l() {
    sh_reset(0);
    sh_sprite(0, TH14_NOTE_BLUE, 0);
    sh_aim(0, 0);
    sh_ring(0, 1);
    sh_count(0, 1, 1);
    sh_angle(0, -90deg, 0deg);
    sh_speed(0, 3.2fx, 0fx);
    loop {
        for i in 0..15 {
            note_volley(-1.2fx);
            wait(6);
        }
        wait(20);
    }
}

// 源 675-686 BossBCard3_at2：固定扇形6路、中轴 ANGLE_PLAYER、间距 0.34906584rad(20°)、
// 大玉(type18)色3、速度1.2，外加大玉 ANIM 的 4*速度退位移。
sub at2_fire() {
    var base: angle = aim_player();
    for i in 0..6 {
        var a: angle = base + ((i * 3641 - 9102) as angle);
        var x: fx = $self_x - 4.8fx * cos(a);
        var y: fx = $self_y - 4.8fx * sin(a);
        _ = fire(TH14_BIG_BALL, 3, x, y, 1.2fx, a, none, none);
    }
}

// 源 599-613：每半程 60帧停 + 220帧横移 + at2；两段合 560 帧，at2 间隔 280 帧。
// 源 584/586/590/597 的入场等待：T60、T120 首发流、T240 进入循环。
async sub card_pattern() {
    boss_x_move(160fx, 60, 1);
    wait(60);
    wait(60);
    spawn stream_at();
    if global(GVAR_RANK) >= RANK_HARD { spawn stream_at_h(); }
    if global(GVAR_RANK) >= RANK_LUNATIC { spawn stream_at_l(); }
    wait(120);
    loop {
        wait(60);
        boss_x_move(-160fx, 220, 0);
        at2_fire();
        wait(60);
        boss_x_move(160fx, 220, 0);
        at2_fire();
    }
}

// 源 804-829 BossBDead（超时路径：TIMEOUT≠0 → Ecl_EtBreak2_ni）。
// 超时收段由 spell 机构自动清弹（不转星），覆盖 ni 的扩张 etClear；
// 掉落/音效/ANM/震屏/BossItemPhase 按共用取舍省略。
sub boss_dead() {
    // 源 809/818：moveVel(RANDRAD,0.4) + moveRand(60,0,0.4)。死亡点 |x|=140>25，
    // 命中 moveRand 外侧分支：±60°，x>25 一侧加 π；y=128∈[112,144] 不改向。
    var u: fx = ((rand(65536) - 32768) as fx) * 0.000030517578125fx;
    var a: int = (u * 10923fx) as int;
    if $self_x > 25fx { a = a + 32768; }
    move_vel(0, a as angle, 0.4fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_LINEAR);
    wait(60);
    clear_bullets();
}

async sub boss_main() {
    // 源 BossB 入口状态（st04bs2.ecl.txt:25-26）：框 48/48 → 半径 24；体碰按源保留。
    // 源两次 setInvuln(60) 由本卡无敌外壳的 65535 覆盖（不模拟 DPS）。
    set_hitbox(24fx);
    set_hurtbox(24fx);
    set_invuln(65535);
    spell_begin(0, SPELL_ID, card_pattern, SPELL_TIME, 0, 0, 1);
    wait_spell();
    boss_dead();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 9999, 0, 0, 0, boss_main);
    loop { wait(60); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
